/**
 * The scene description format. Every type here is a plain, JSON-serializable
 * object: a scene can be written by hand, generated by a tool, stored as JSON
 * and passed straight to {@link renderSvg}.
 *
 * Units are scene units; at `zoom: 1` one unit is one SVG pixel.
 * Axes: x right, y down, z toward the viewer. Angles are in degrees.
 */

/**
 * A 3D position or offset. Missing components default to 0, so
 * `{ y: -20 }` means `{ x: 0, y: -20, z: 0 }`.
 */
export interface VectorInput {
  /** Rightward offset. Default 0. */
  x?: number;
  /** Downward offset. Default 0. */
  y?: number;
  /** Offset toward the viewer. Default 0. */
  z?: number;
}

/**
 * Euler angles in degrees, applied about z first, then y, then x.
 * Positive `z` turns clockwise on screen; positive `y` moves the +x side away
 * from the viewer; positive `x` moves the bottom (+y) side toward the viewer.
 */
export interface RotationInput {
  /** Degrees about the x axis. Default 0. */
  x?: number;
  /** Degrees about the y axis. Default 0. */
  y?: number;
  /** Degrees about the z axis. Default 0. */
  z?: number;
}

/** Options shared by every node. */
export interface NodeBase {
  /** Optional name. Used in error messages; not emitted in the SVG. */
  id?: string;
  /** Position relative to the parent. Default `{ x: 0, y: 0, z: 0 }`. */
  translate?: VectorInput;
  /** Rotation relative to the parent, in degrees. Default no rotation. */
  rotate?: RotationInput;
  /**
   * Scale relative to the parent: one number for uniform scale or a vector
   * per axis. Stroke widths scale with the overall size. Default 1.
   */
  scale?: number | VectorInput;
  /** Set to false to hide this node and all of its children. Default true. */
  visible?: boolean;
  /** Child nodes. They inherit this node's translate, rotate and scale. */
  children?: Node[];
}

/** Options shared by every drawable shape. */
export interface ShapeBase extends NodeBase {
  /**
   * Any CSS color: `#rgb`, `#rrggbb`, `#rrggbbaa`, `rgb(...)`, `hsl(...)`,
   * a named color such as `tomato`, or `currentColor`. Default `"#333"`.
   */
  color?: string;
  /**
   * Width of the round-capped outline in scene units. A thick stroke on a
   * single point draws a sphere-like dot; on a line it draws a tube.
   * Use 0 for no outline (then set `fill: true` or nothing is drawn). Default 1.
   */
  stroke?: number;
  /** Fill the inside of the shape with `color`. Default false. */
  fill?: boolean;
}

/** An invisible container used to move, rotate and scale its children together. */
export interface GroupNode extends NodeBase {
  type: 'group';
}

/** A cubic Bezier segment from the previous point, through two control points, to an end point. */
export interface BezierInput {
  /** `[control1, control2, end]`. */
  bezier: [VectorInput, VectorInput, VectorInput];
}

/** A point in a path: a straight line to a point, or a Bezier curve. */
export type PathPoint = VectorInput | BezierInput;

/**
 * A free-form path. One point draws a dot, two points draw a line, more
 * points draw a polyline or polygon. The first entry must be a plain point.
 */
export interface PathNode extends ShapeBase {
  type: 'path';
  /** The points, in local coordinates. At least one. */
  path: PathPoint[];
  /** Connect the last point back to the first. Default false. */
  closed?: boolean;
}

/** An ellipse (or circle) in the local x/y plane, centered on the origin. */
export interface EllipseNode extends ShapeBase {
  type: 'ellipse';
  /** Diameter of a circle. Use this or `width` and `height`. */
  diameter?: number;
  /** Width along x. Use with `height`, instead of `diameter`. */
  width?: number;
  /** Height along y. Use with `width`, instead of `diameter`. */
  height?: number;
}

/** A rectangle in the local x/y plane, centered on the origin. */
export interface RectNode extends ShapeBase {
  type: 'rect';
  /** Width along x. */
  width: number;
  /** Height along y. */
  height: number;
}

/** A regular polygon in the local x/y plane, centered on the origin, with one corner pointing up (-y). */
export interface PolygonNode extends ShapeBase {
  type: 'polygon';
  /** Number of sides, an integer of at least 3. */
  sides: number;
  /** Distance from the center to each corner. */
  radius: number;
}

/** Any node that can appear in a scene tree. */
export type Node = GroupNode | PathNode | EllipseNode | RectNode | PolygonNode;

/** The `type` values a node can have. */
export type NodeType = Node['type'];

/** A complete scene: the viewport plus the tree of nodes. */
export interface Scene {
  /** Width of the output image in pixels. */
  width: number;
  /** Height of the output image in pixels. */
  height: number;
  /** Multiplies every distance and stroke width. Default 1. */
  zoom?: number;
  /** Background color. Default none (transparent). */
  background?: string;
  /** Accessible title, emitted as `<title>` and `aria-label`. */
  title?: string;
  /**
   * View rotation applied to the whole scene, in degrees. For example
   * `{ x: -15 }` looks down on the scene from slightly above.
   */
  rotate?: RotationInput;
  /** Top-level nodes. The scene origin is the center of the image. */
  children: Node[];
}
